    /// `POST /access/domains/{realm}/sync`
    ///
    /// Syncs users and/or groups from the configured LDAP to user.cfg. NOTE: Synced groups will have the name 'name-$realm', so make sure those groups do not exist to prevent overwriting.
    public struct PostAccessDomainsSync: PVEAPIRequest, Hashable {
        public typealias Response = String
        public static let method: HTTPMethod = .post
        public static let pathTemplate = "/access/domains/{realm}/sync"
        public static let schemaName = "sync"

        /// Authentication domain ID
        ///
        /// Format: `pve-realm`. Max length: 32.
        public var realm: String

        /// If set, does not write anything.
        ///
        /// Default: `0`.
        public var dryRun: Bool?

        /// Enable newly synced users immediately.
        ///
        /// Default: `1`.
        public var enableNew: Bool?

        /// DEPRECATED: use 'remove-vanished' instead. If set, uses the LDAP Directory as source of truth, deleting users or groups not returned from the sync and removing all locally modified properties of synced users. If not set, only syncs information which is present in the synced data, and does not delete or modify anything else.
        public var full: Bool?

        /// DEPRECATED: use 'remove-vanished' instead. Remove ACLs for users or groups which were removed from the config during a sync.
        public var purge: Bool?

        /// A semicolon-separated list of things to remove when they or the user vanishes during a sync. The following values are possible: 'entry' removes the user/group when not returned from the sync. 'properties' removes the set properties on existing user/group that do not appear in the source (even custom ones). 'acl' removes acls when the user/group is not returned from the sync. Instead of a list it also can be 'none' (the default).
        ///
        /// Default: `none`.
        public var removeVanished: String?

        /// Select what to sync.
        public var scope: Scope?

        public init(realm: String) {
            self.realm = realm
        }

        public var path: String { PathBuilder.path("access", "domains", realm.parameterValue, "sync") }

        public var parameters: [(String, String)] {
            var result: [(String, String)] = []
            if let value = dryRun { result.append(("dry-run", value.parameterValue)) }
            if let value = enableNew { result.append(("enable-new", value.parameterValue)) }
            if let value = full { result.append(("full", value.parameterValue)) }
            if let value = purge { result.append(("purge", value.parameterValue)) }
            if let value = removeVanished { result.append(("remove-vanished", value.parameterValue)) }
            if let value = scope { result.append(("scope", value.parameterValue)) }
            return result
        }

        /// Select what to sync.
        public enum Scope: String, Sendable, Hashable, CaseIterable, Codable, PVEParameterValue {
